{
  "concepts": [
    {
      "conditions": [],
      "definition": "Application-neutral traversal-occurrence profile owning record, relation, identity, causal, effect-boundary, frontier and refusal laws. It supplies no operation or judgment authority and is available but inactive for a Product without complete Product adoption.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1451,
          "quote": "This profile owns only the application-neutral record, relation, identity,\ncausal, effect-boundary, frontier and refusal laws above.",
